# ---------- ghi docx ----------
doc = Document()
doc.add_paragraph(f"[EXAM:TITLE]{TITLE}[/EXAM:TITLE]")
doc.add_paragraph(f"[EXAM:TIME]{TIME}[/EXAM:TIME]")

def add_q(p, num, opts, ans, hint, qtext=None):
    doc.add_paragraph(f"[Q:{num}]")
    if qtext:
        doc.add_paragraph(f"[QTEXT]{qtext}[/QTEXT]")
    for k, o in zip("ABCD", opts):
        doc.add_paragraph(f"[OPTION:{k}]{o}[/OPTION:{k}]")
    doc.add_paragraph(f"[ANSWER]{ans}[/ANSWER]")
    doc.add_paragraph(f"[HINT]{hint}[/HINT]")
    doc.add_paragraph("[SHUFFLE_Q]yes[/SHUFFLE_Q]")
    doc.add_paragraph("[SHUFFLE_A]yes[/SHUFFLE_A]")
    doc.add_paragraph(f"[/Q:{num}]")

def add_group(part, gid, passage, qs):
    doc.add_paragraph(f"[GROUP:{gid}]")
    doc.add_paragraph("[PASSAGE]")
    for line in passage.split("\n"):
        doc.add_paragraph(line)
    doc.add_paragraph("[/PASSAGE]")
    for (num, *rest) in qs:
        if part == 6:
            opts, ans, hint = rest
            add_q(part, num, opts, ans, hint)
        else:
            qtext, opts, ans, hint = rest
            add_q(part, num, opts, ans, hint, qtext)
    doc.add_paragraph(f"[/GROUP:{gid}]")

doc.add_paragraph("[PART:5]")
for (num, stem, opts, ans, hint) in part5:
    add_q(5, num, opts, ans, hint, qtext=stem)

doc.add_paragraph("[PART:6]")
for (gid, passage, qs) in part6:
    add_group(6, gid, passage, qs)

doc.add_paragraph("[PART:7]")
for (gid, passage, qs) in part7:
    add_group(7, gid, passage, qs)

out = "C:/Giua-ky/TOEIC_Reading_Test9_Tagged.docx"
doc.save(out)
print("da ghi:", out)
print("so cau Part5:", len(part5), "| Part6:", sum(len(q) for _,_,q in part6), "| Part7:", sum(len(q) for _,_,q in part7))
